  ) AS a(oid, nome)
  JOIN public.demandas d ON d.origem = 'notion' AND d.origem_id = a.oid
  JOIN LATERAL (
    SELECT p.id FROM public.profiles p
    WHERE public.normalizar_texto(p.nome) LIKE a.nome || '%'
      AND p.ativo IS DISTINCT FROM false
    ORDER BY p.created_at LIMIT 1
  ) p ON true
  WHERE d.responsavel_id IS DISTINCT FROM p.id
  ON CONFLICT DO NOTHING;
