ALTER TABLE public.demandas       ENABLE TRIGGER trg_notify_demanda_ins;
ALTER TABLE public.demanda_apoios ENABLE TRIGGER trg_notify_demanda_apoio;

-- ═══════════════════════════════════════════════════════════════════════
-- VERIFICAÇÃO FINAL
-- ═══════════════════════════════════════════════════════════════════════
SELECT 'demandas importadas do Notion' AS verificacao,
       count(*)::text AS resultado, '537' AS esperado
FROM public.demandas WHERE origem = 'notion'
UNION ALL
SELECT 'do Davi', count(*)::text, '251'
FROM public.demandas d JOIN public.profiles p ON p.id = d.responsavel_id
WHERE d.origem = 'notion' AND (p.email = 'davssvoos@gmail.com' OR public.normalizar_texto(p.nome) LIKE 'davi%')
UNION ALL
SELECT 'do Erik', count(*)::text, '286'
FROM public.demandas d JOIN public.profiles p ON p.id = d.responsavel_id
WHERE d.origem = 'notion' AND public.normalizar_texto(p.nome) LIKE 'erik%'
UNION ALL
SELECT 'por status', string_agg(status || '=' || n::text, ', ' ORDER BY status), '(informativo)'
FROM (SELECT status, count(*) AS n FROM public.demandas WHERE origem='notion' GROUP BY status) t
UNION ALL
SELECT 'com cliente casado no cadastro', count(*)::text, '(informativo — QAP vai religar o resto)'
FROM public.demandas WHERE origem = 'notion' AND cliente_id IS NOT NULL
UNION ALL
SELECT 'apoios criados', count(*)::text, '(informativo — so quem tem conta)'
FROM public.demanda_apoios a JOIN public.demandas d ON d.id = a.demanda_id
WHERE d.origem = 'notion'
UNION ALL
SELECT 'notificacoes reativadas', count(*)::text, '2'
FROM pg_trigger WHERE NOT tgisinternal AND tgenabled = 'O'
  AND tgname IN ('trg_notify_demanda_ins','trg_notify_demanda_apoio');
